import re

class Scope:
    """One dictionary, plus a link to the scope around it."""
    def __init__(self, parent=None):
        self.vars = {}
        self.parent = parent

    def lookup(self, name):
        scope = self
        while scope is not None:            # walk outward along the links
            if name in scope.vars:
                return scope.vars[name]
            scope = scope.parent
        raise NameError(f"undefined variable {name!r}")

    def define(self, name, value):
        self.vars[name] = value             # this scope only

    def assign(self, name, value):
        scope = self
        while scope is not None:            # update the x we find
            if name in scope.vars:
                scope.vars[name] = value
                return
            scope = scope.parent
        raise NameError(f"undefined variable {name!r}")


class Parser:
    def __init__(self, text):
        # Names have several characters, so split the text into tokens first.
        self.tokens = re.findall(r"\d+|[A-Za-z_]\w*|\S", text)
        self.pos = 0
        self.scope = Scope()                # the global scope

    def peek(self):
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return None

    def match(self, token):
        if self.peek() == token:
            self.pos += 1
            return True
        return False

    def E(self):
        value = self.T()
        while self.peek() in ("+", "-"):
            op = self.peek()
            self.match(op)
            right = self.T()
            value = value + right if op == "+" else value - right
        return value

    def T(self):
        value = self.F()
        while self.peek() in ("*", "/"):
            op = self.peek()
            self.match(op)
            right = self.F()
            value = value * right if op == "*" else value / right
        return value

    def F(self):
        token = self.peek()
        if self.match("("):
            value = self.E()
            self.match(")")
            return value
        self.match(token)
        if token.isdigit():
            return int(token)
        return self.scope.lookup(token)     # lookup: walk the chain

    def statement(self):
        token = self.peek()
        self.match(token)
        if token == "{":
            self.scope = Scope(self.scope)  # enter: push a new scope
            while not self.match("}"):
                self.statement()
            self.scope = self.scope.parent  # leave: back to the parent
            return
        if token == "print":
            print(self.E())
        elif token == "let":
            name = self.peek()
            self.match(name)
            self.match("=")
            self.scope.define(name, self.E())
        else:
            self.match("=")
            self.scope.assign(token, self.E())
        self.match(";")

    def parse(self):
        while self.peek() is not None:
            self.statement()


